INSERT INTO `p3_uniprot` VALUES (41,'development','mouse','10090','22059','Q3UGQ1','Cellular tumor antigen p53',0,0,'exact_GeneID_cross_reference','Multifunctional transcription factor that induces cell cycle arrest, DNA repair or apoptosis upon binding to its target DNA sequence. Acts as a tumor suppressor in many tumor types; induces growth arrest or apoptosis depending on the physiological circumstances and cell type. Negatively regulates cell division by controlling expression of a set of genes required for this process. One of the activated genes is an inhibitor of cyclin-dependent kinases. Apoptosis induction seems to be mediated either by stimulation of BAX and FAS antigen expression, or by repression of Bcl-2 expression','[\"GO:0000976\",\"GO:0003700\",\"GO:0031625\",\"GO:0097371\"]','[\"GO:0009416\",\"GO:0010212\",\"GO:0051262\",\"GO:0097190\"]','[\"GO:0005759\",\"GO:0005783\",\"GO:0016605\"]','[\"SL-0086\",\"SL-0095\",\"SL-0170\",\"SL-0191\",\"SL-0465\"]','[\"Cytoplasm\",\"Endoplasmic reticulum\",\"Mitochondrion matrix\",\"Nucleus\",\"Nucleus, PML body\"]','[{\"evidences\":[{\"evidenceCode\":\"ECO:0000256\",\"source\":\"RuleBase\",\"id\":\"RU003304\"}],\"value\":\"Multifunctional transcription factor that induces cell cycle arrest, DNA repair or apoptosis upon binding to its target DNA sequence. Acts as a tumor suppressor in many tumor types; induces growth arrest or apoptosis depending on the physiological circumstances and cell type. Negatively regulates cell division by controlling expression of a set of genes required for this process. One of the activated genes is an inhibitor of cyclin-dependent kinases. Apoptosis induction seems to be mediated either by stimulation of BAX and FAS antigen expression, or by repression of Bcl-2 expression\"}]','[{\"id\":\"GO:0005783\",\"aspect\":\"C\",\"term\":\"endoplasmic reticulum\",\"evidence_type\":\"IEA:UniProtKB-SubCell\",\"evidences\":[]},{\"id\":\"GO:0005759\",\"aspect\":\"C\",\"term\":\"mitochondrial matrix\"